SELECT 'gongkao', '基础公式应用', 'kp-trv-b-formula', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "基础公式应用"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "综合考查 S=VT 的变式，结合基本的加减法建立一元一次方程。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "没有花里胡哨的相遇追及，只有简单的“走了一段，又走了一段”。通常要求列基础方程。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "利用“时间总和”或“路程总和”列等式。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画出线段图, 标出各段的 S, V, T] --> B[设未知数 (通常设题目所求的量)]\nB --> C[利用 S=VT 将所有线段表达出来]\nC --> D[拼接所有线段, 列出总和方程]\nD --> E[求解]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 一段路长 100km。前一半以 40km/h 行驶，后一半以 60km/h 行驶。求总时间？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "切分路程：S1 = 50，S2 = 50。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算时间1：T1 = 50 / 40 = 1.25 小时。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算时间2：T2 = 50 / 60 = 5/6 小时。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求和：总时间 = 5/4 + 5/6 = 25/12 小时。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "平均速度陷阱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "前半程40，后半程60，平均速度绝不是 50！这种直接把两个速度相加除以2的做法是公考行测中死得最惨的常识错误。"}]}]}]}$$ AS jsonb), NULL, '基础公式应用的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "基础公式应用"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_b_formula", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
